from typing import List

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True

    def search(self, word: str) -> bool:
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end_of_word

def solve(data: dict) -> bool:
    text = data['text']
    words = set(data['words'])

    trie = Trie()
    for word in words:
        trie.insert(word)

    n = len(text)
    dp = [False] * (n + 1)
    dp[0] = True

    for i in range(1, n + 1):
        for j in range(i):
            if dp[j] and trie.search(text[j:i]):
                dp[i] = True
                break

    return dp[n]

# Test cases
print(solve({"text": "", "words": []}))  # Output: True
print(solve({"text": "leetcode", "words": ["leet", "code"]}))  # Output: True
print(solve({"text": "catsandog", "words": ["cats", "dog", "sand", "and", "cat"]}))  # Output: False
print(solve({"text": "aaaa", "words": ["a", "aa"]}))  # Output: True

from collections import defaultdict

def solve(data):
    text = data["text"]
    words = set(data["words"])

    # Create a Trie to store all words
    trie = defaultdict(set)
    for word in words:
        current_node = trie
        for char in word:
            current_node[char].add(word)
        current_node['end'] = True

    @lru_cache(None)
    def can_segment(i):
        if i == len(text):
            return True
        if text[i] not in trie:
            return False

        for end in trie[text[i]]:
            if end != 'end' and can_segment(i + len(end)):
                return True

    return can_segment(0)

from typing import List, Dict

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_word = True

    def search(self, word: str) -> bool:
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_word

def can_segment_text(text: str, words: List[str]) -> bool:
    trie = Trie()
    for word in words:
        trie.insert(word)

    n = len(text)
    dp = [False] * (n + 1)
    dp[0] = True  # Empty text can be segmented into zero words

    for i in range(1, n + 1):
        for j in range(i):
            if dp[j] and trie.search(text[j:i]):
                dp[i] = True
                break

    return dp[n]

# Example usage
data = {
    "text": "",
    "words": []
}
print(can_segment_text(**data))  # Output: True

data = {
    "text": "leetcode",
    "words": ["leet", "code"]
}
print(can_segment_text(**data))  # Output: True

data = {
    "text": "catsandog",
    "words": ["cats", "dog", "sand", "and", "cat"]
}
print(can_segment_text(**data))  # Output: False

data = {
    "text": "aaaa",
    "words": ["a", "aa"]
}
print(can_segment_text(**data))  # Output: True

from typing import List

class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        if not s:
            return True

        wordSet = set(wordDict)
        n = len(s)

        @cache
        def dp(i):
            if i == n:
                return True

            for j in range(i + 1, n + 1):
                if s[i:j] in wordSet and dp(j):
                    return True

            return False

        return dp(0)
